import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

// issue #12: 1,000 x (1 - 0.1) = 900. No bulk discount under 10 lines.
test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

const lines = (n) => Array.from({ length: n }, () => ({ price: 1000, qty: 1 }));

// issue #12: 10,000 x (1 - 0.1) = 9,000, then 5% bulk once = 8,550.
test('bulk discount is applied once, after the customer discount', () => {
  assert.equal(total(lines(10), 0.1), 8550);
});

// 9 lines is below the bulk threshold: 9,000 x (1 - 0.1) = 8,100.
test('no bulk discount under 10 lines', () => {
  assert.equal(total(lines(9), 0.1), 8100);
});

// issue #12: totals at discount rate 0 stay as they were (10,000 x 0.95 = 9,500).
test('bulk discount alone at discount rate 0', () => {
  assert.equal(total(lines(10), 0), 9500);
  assert.equal(total(lines(10)), 9500);
});

// issue #12: rate-0 totals stay as they were, including rounding to the
// nearest unit: 10,001 x 0.95 = 9,500.95 -> 9,501.
test('total at discount rate 0 is still rounded to the nearest unit', () => {
  assert.equal(total([...lines(9), { price: 1001, qty: 1 }], 0), 9501);
});
